export function scoreAnswers(answers){
 if(!Array.isArray(answers)||answers.length!==questions.length||answers.some((a,i)=>!Number.isInteger(a)||!questions[i].options[a]))throw new Error('열두 질문에 모두 답해주세요.');
 const totals=cards.map(()=>0);answers.forEach((a,i)=>questions[i].options[a].scores.forEach((id,j)=>totals[id]+=j===0?2:1));
 const max=Math.max(...totals);return {totals,candidates:cards.filter((_,i)=>totals[i]===max)};
}
